#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007
#define MAXN 1000

typedef struct Node {
    int type; // 0: substance, 1: optional substance, 2: alt, 3: or, 4: optional alt, 5: optional or
    int child_count;
    int children[10];
} Node;

Node nodes[MAXN + 1];
long long dp[MAXN + 1][2]; // dp[node][0] = ways when node is not chosen, dp[node][1] = ways when node is chosen

void dfs(int u) {
    if (nodes[u].type == 0) { // non-optional substance
        dp[u][0] = 0;
        dp[u][1] = 1;
    } else if (nodes[u].type == 1) { // optional substance
        dp[u][0] = 1;
        dp[u][1] = 1;
    } else if (nodes[u].type == 2 || nodes[u].type == 4) { // alt (non-optional or optional)
        // alt: exactly one child must be selected if non-optional, zero or one if optional
        long long ways_not_chosen = 1;
        long long ways_chosen = 0;
        for (int i = 0; i < nodes[u].child_count; i++) {
            int v = nodes[u].children[i];
            dfs(v);
            // For alt, if node is chosen, exactly one child must be chosen
            // If node is not chosen, no child is chosen
        }
        // compute ways when node is chosen: sum over children of (ways child chosen * product of ways other children not chosen)
        long long prod_all_not = 1;
        for (int i = 0; i < nodes[u].child_count; i++) {
            int v = nodes[u].children[i];
            prod_all_not = (prod_all_not * dp[v][0]) % MOD;
        }
        for (int i = 0; i < nodes[u].child_count; i++) {
            int v = nodes[u].children[i];
            long long term = (dp[v][1] * prod_all_not) % MOD;
            term = (term * mod_inv(dp[v][0])) % MOD;
            ways_chosen = (ways_chosen + term) % MOD;
        }
        if (nodes[u].type == 2) { // non-optional alt
            dp[u][0] = 0;
            dp[u][1] = ways_chosen;
        } else { // optional alt
            dp[u][0] = 1; // not chosen: no child chosen
            dp[u][1] = ways_chosen; // chosen: exactly one child chosen
        }
    } else if (nodes[u].type == 3 || nodes[u].type == 5) { // or (non-optional or optional)
        // or: at least one child must be chosen if non-optional, zero or more if optional
        long long prod_all = 1;
        for (int i = 0; i < nodes[u].child_count; i++) {
            int v = nodes[u].children[i];
            dfs(v);
            long long sum_child = (dp[v][0] + dp[v][1]) % MOD;
            prod_all = (prod_all * sum_child) % MOD;
        }
        long long all_not = 1;
        for (int i = 0; i < nodes[u].child_count; i++) {
            int v = nodes[u].children[i];
            all_not = (all_not * dp[v][0]) % MOD;
        }
        long long at_least_one = (prod_all - all_not + MOD) % MOD;
        if (nodes[u].type == 3) { // non-optional or
            dp[u][0] = 0;
            dp[u][1] = at_least_one;
        } else { // optional or
            dp[u][0] = 1; // not chosen: no child chosen
            dp[u][1] = at_least_one; // chosen: at least one child chosen
        }
    }
}

long long mod_pow(long long a, long long e) {
    long long res = 1;
    while (e) {
        if (e & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return res;
}

long long mod_inv(long long a) {
    return mod_pow(a, MOD - 2);
}

