void dfs(int u) {
    for (int i = 0; i < deg[u]; i++) {
        dfs(child[u][i]);
    }

    if (node[u].type == 0) {
        // substance node
        dp[u] = node[u].optional ? 2 : 1;
    } else if (node[u].type == 1) {
        // alt node: choose exactly one child, or none if optional
        ll sum = 0;
        for (int i = 0; i < deg[u]; i++) {
            sum += dp[child[u][i]];
            if (sum >= MOD) sum -= MOD;
        }
        if (node[u].optional) sum = (sum + 1) % MOD;
        dp[u] = sum;
    } else {
        // or node: choose any non-empty subset of children, one combination from each chosen child
        ll prod = 1;
        for (int i = 0; i < deg[u]; i++) {
            prod = (prod * (dp[child[u][i]] + 1)) % MOD;
        }
        // subtract the case where no child is chosen
        dp[u] = (prod - 1 + MOD) % MOD;
        if (node[u].optional) dp[u] = (dp[u] + 1) % MOD;
    }
}

