        // optional alt: can also select none
        long long sum = 0;
        for (long long val : child_vals) {
            sum = (sum + val) % MOD;
        }
        if (t == 4) {
            // optional: can also choose none
            ans = (1 + sum) % MOD;
        } else {
            ans = sum % MOD;
        }
    } else { // or (R) or optional or (R?)
        // or: at least one child must be selected (if non-optional)
        // optional or: can also select none
        long long prod = 1;
        for (long long val : child_vals) {
            prod = (prod * (val + 1)) % MOD;
        }
        if (t == 5) {
            // optional: can select none
            ans = prod % MOD;
        } else {
            // non-optional: exclude the case where none selected
            ans = (prod - 1 + MOD) % MOD;
        }
    }
    return dp[u] = ans;
}

