public class Main {
    static final int MOD = 1_000_000_007;
    static List<Integer>[] children;
    static String[] types;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine());
        types = new String[N + 1];
        children = new ArrayList[N + 1];

        for (int i = 1; i <= N; i++) {
            types[i] = br.readLine().trim();
            children[i] = new ArrayList<>();
        }

        for (int i = 0; i < N - 1; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int s = Integer.parseInt(st.nextToken());
            int t = Integer.parseInt(st.nextToken());
            children[s].add(t);
        }

        long result = dfs(1)[0];
        System.out.println(result % MOD);
    }

    // returns [totalCombinations, emptyCombinationPossible]
    static long[] dfs(int node) {
        String type = types[node];
        boolean optional = type.endsWith("?");
        char kind = type.charAt(0);

        // Leaf: substance node
        if (children[node].isEmpty()) {
            if (optional) {
                // optional substance: choose or not
                return new long[]{2, 1};
            } else {
                // must choose
                return new long[]{1, 0};
            }
        }

        // Selection node
        long total = 1;
        long emptyProduct = 1;
        boolean allEmpty = true;

        for (int child : children[node]) {
            long[] childRes = dfs(child);
            total = (total * childRes[0]) % MOD;
            emptyProduct = (emptyProduct * childRes[1]) % MOD;
            if (childRes[1] == 0) allEmpty = false;
        }

        long result;
        long emptyPossible = 0;

        if (kind == 'R') { // OR
            // total combinations = product(child totals) - product(child empties) if not optional
            if (optional) {
                result = total;
                emptyPossible = emptyProduct;
            } else {
                result = (total - emptyProduct + MOD) % MOD;
                emptyPossible = 0;
            }
        } else { // ALT
            // sum of (product of all other children totals) for each child
            int m = children[node].size();
            long[] prefix = new long[m + 1];
            long[] suffix = new long[m + 1];
            prefix[0] = 1;
            suffix[m] = 1;

            for (int i = 0; i < m; i++) {
                long[] childRes = dfs(children[node].get(i));
                prefix[i + 1] = (prefix[i] * childRes[0]) % MOD;
            }
            for (int i = m - 1; i >= 0; i--) {
                long[] childRes = dfs(children[node].get(i));
                suffix[i] = (suffix[i + 1] * childRes[0]) % MOD;
            }

            long sum = 0;
            for (int i = 0; i < m; i++) {
                long ways = (prefix[i] * suffix[i + 1]) % MOD;
                sum = (sum + ways) % MOD;
            }

            if (optional) {
                result = (1 + sum) % MOD; // also possible to choose nothing
                emptyPossible = 1;
            } else {
                result = sum;
                emptyPossible = 0;
            }
        }

        return new long[]{result, emptyPossible};
    }
}

