public class Main {
    static final long MOD = 1_000_000_007L;

    static class Node {
        char kind; // 'E', 'A', 'R'
        boolean optional;
        ArrayList<Integer> children = new ArrayList<>();
    }

    static Node[] nodes;
    static long[] dp;

    static long dfs(int u) {
        Node node = nodes[u];

        if (node.kind == 'E') {
            // Substance node: choose it if non-optional, otherwise choose or not choose.
            dp[u] = node.optional ? 2L : 1L;
            return dp[u];
        }

        long res = 0;
        if (node.kind == 'A') {
            // alt: choose exactly one child, or none if optional
            for (int v : node.children) {
                res += dfs(v);
                if (res >= MOD) res -= MOD;
            }
            if (node.optional) {
                res++;
                if (res >= MOD) res -= MOD;
            }
        } else {
            // R = or: choose any non-empty subset of children, taking one valid combination from each chosen child
            long prod = 1;
            for (int v : node.children) {
                long ways = dfs(v);
                prod = (prod * (ways + 1)) % MOD; // choose this child or not
            }
            if (node.optional) {
                // empty subset allowed
                res = prod;
            } else {
                // exclude empty subset
                res = (prod - 1 + MOD) % MOD;
            }
        }

        dp[u] = res;
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();

        nodes = new Node[N + 1];
        for (int i = 1; i <= N; i++) {
            nodes[i] = new Node();
            String s = fs.next();
            if (s.endsWith("?")) {
                nodes[i].optional = true;
                s = s.substring(0, s.length() - 1);
            }
            nodes[i].kind = s.charAt(0);
        }

        for (int i = 0; i < N - 1; i++) {
            int parent = fs.nextInt();
            int child = fs.nextInt();
            nodes[parent].children.add(child);
        }

        dp = new long[N + 1];
        System.out.println(dfs(1));
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

