        elif info == "R":
            node_type.append(4)
        elif info == "R?":
            node_type.append(5)

    # returns (combinations where node is chosen, combinations where node is not chosen)
    def dfs(u):
        if node_type[u] == 0:
            # non-optional substance: must be chosen
            return (1, 0)
        elif node_type[u] == 1:
            # optional substance: can choose or not
            return (1, 1)
        else:
            child_results = [dfs(v) for v in children[u]]
            if node_type[u] in (2, 3):  # alt type
                # exactly one child chosen, unless optional then also none
                total_chosen = 0
                total_not_chosen = 1
                for chosen, not_chosen in child_results:
                    total_chosen = (total_chosen * not_chosen) % MOD
                # Actually alt: exactly one child chosen
                # sum over children: (chosen_i * product of not_chosen_j for j != i)
                prod_not = 1
                for _, not_chosen in child_results:
                    prod_not = (prod_not * not_chosen) % MOD
                total_chosen = 0
                for chosen, not_chosen in child_results:
                    total_chosen = (total_chosen + chosen * prod_not * pow(not_chosen, MOD-2, MOD)) % MOD
                # if optional, also allow none chosen
                if node_type[u] == 3:
                    total_not_chosen = 1  # none chosen
                else:
                    total_not_chosen = 0
                return (total_chosen, total_not_chosen)
            else:  # or type (4, 5)
                # at least one child chosen
                prod_all = 1
                prod_not = 1
                for chosen, not_chosen in child_results:
                    prod_all = (prod_all * (chosen + not_chosen)) % MOD
                    prod_not = (prod_not * not_chosen) % MOD
                total_chosen = (prod_all - prod_not) % MOD
                if node_type[u] == 5:
                    total_not_chosen = 1
                else:
                    total_not_chosen = 0
                return (total_chosen, total_not_chosen)

    chosen_root, _ = dfs(0)
    print(chosen_root % MOD)

